#!/usr/bin/env bash
# Expands Dev Files to cover the WHOLE system, not just the Agent/kiosk
# side: app/ (including every Jinja template), migrations/, run.py, and
# config.py are now browsable and editable too, alongside the existing
# agent/, service_files/, requirements.txt.
#
# IMPORTANT — two very different risk profiles now share this page:
#   - agent/ and service_files/ only ever reach a kiosk after Publish AND
#     a reinstall. Editing them can't affect anything running right now.
#   - app/, migrations/, run.py, config.py are this Admin Panel's own
#     code. This server runs with Flask's debug reloader (run.py has
#     debug=True), which restarts the whole process the moment any
#     watched .py file changes — so a mistake here (a syntax error, a
#     broken import) can take the site down IMMEDIATELY, not just affect
#     a future install. The UI now says this explicitly on both the file
#     list and the editor itself, with a stronger confirm() before saving
#     anything under those paths.
#
# SECURITY FIX included in this same push: publish() (which rebuilds the
# tarball actually installed on kiosk hardware) was audited and given its
# own separate, hardcoded scope (KIOSK_SHIP_ROOT_DIRS/FILES = agent/,
# service_files/, requirements.txt only) so it can NEVER inherit the
# broader browsing/editing scope above - verified by actually running
# Publish after this expansion and confirming the resulting tarball still
# contains only agent/service_files/requirements.txt, nothing from app/
# or config.py.
#
# Also excludes __pycache__/.git/.pyc from listing, download, and zip
# upload (even a zip entry that would otherwise resolve inside an allowed
# directory is rejected if it targets one of these) — tested directly
# before shipping.
#
# No database migration in this push.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app/blueprints/dev_files.py app/templates/dev_files run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run push_dev_files.sh first, then this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS/templates/dev_files"
cp app/blueprints/dev_files.py "backups/$TS/dev_files.py.bak" 2>/dev/null || true
cp app/templates/dev_files/index.html "backups/$TS/templates/dev_files/index.html.bak" 2>/dev/null || true
cp app/templates/dev_files/edit.html "backups/$TS/templates/dev_files/edit.html.bak" 2>/dev/null || true
echo "==> Backed up existing files to backups/$TS/"

echo "==> Writing app/blueprints/dev_files.py"
base64 -d > app/blueprints/dev_files.py << 'DEV_FILES_PY_B64'

DEV_FILES_PY_B64

echo "==> Writing app/templates/dev_files/index.html"
base64 -d > app/templates/dev_files/index.html << 'DEV_INDEX_HTML_B64'

DEV_INDEX_HTML_B64

echo "==> Writing app/templates/dev_files/edit.html"
base64 -d > app/templates/dev_files/edit.html << 'DEV_EDIT_HTML_B64'

DEV_EDIT_HTML_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/blueprints/dev_files.py').read())"
echo "    syntax OK"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Dev Files now covers the whole system: app/ (incl. every template),"
echo "migrations/, run.py, config.py - alongside agent/, service_files/,"
echo "requirements.txt."
echo ""
echo "Read the warning banner on the page before editing anything under"
echo "app/ or migrations/ - unlike agent/ files, those take effect on"
echo "this live site immediately on save."
echo ""
echo "Publish (the kiosk tarball rebuild) is UNCHANGED - still only ever"
echo "bundles agent/ + service_files/ + requirements.txt, verified after"
echo "this expansion, not just before it."
echo "==================================================================="
